def evaluate(expr: str) -> int:
    def shunting_yard(expr: str) -> list:
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        operators = []
        number = ''
        for char in expr:
            if char.isdigit():
                number += char
            else:
                if number:
                    output.append(int(number))
                    number = ''
                if char in precedence:
                    while operators and precedence[operators[-1]] >= precedence[char]:
                        output.append(operators.pop())
                    operators.append(char)
                elif char == '(':
                    operators.append(char)
                elif char == ')':
                    while operators and operators[-1] != '(':
                        output.append(operators.pop())
                    operators.pop()
        if number:
            output.append(int(number))
        while operators:
            output.append(operators.pop())
        return output

    def postfix_eval(postfix: list) -> int:
        stack = []
        for token in postfix:
            if isinstance(token, int):
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(int(a / b))
        return stack[0]

    postfix = shunting_yard(expr)
    return postfix_eval(postfix)

