def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total_seconds = 0
    current_value = 0
    current_unit = ''

    for char in s:
        if char.isdigit():
            current_value = current_value * 10 + int(char)
        elif char in units:
            if current_unit:
                total_seconds += current_value * units[current_unit]
            current_value = 0
            current_unit = char
        else:
            raise ValueError("Malformed string")

    if current_unit:
        total_seconds += current_value * units[current_unit]

    return total_seconds

