def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    graph = [[] for _ in range(n)]
    visited = [False] * n
    in_stack = [False] * n
    result = []

    def dfs(node):
        if visited[node]:
            return False

        visited[node] = True
        in_stack[
            node] = True

        for neighbor in graph[node]:
            if in_stack[neighbor]:
                return False
            if not visited[neighbor]:
                if not dfs(neighbor):
                    return False

        result.insert(0, node)
        in_stack[node] = False
        return True

    for u, v in edges:
        graph[u].append(v)

    for node in range(n):
        if not visited[node]:
            if not dfs(node):
                return []

    return result

