    def match_pattern(s: str, p: str) -> bool:
        # Base case: both strings are empty
        if not s and not p:
            return True

        # Base case: pattern is empty
        if not p:
            return False

        # Get first character of the pattern
        first_char = p[0]

        # If first character of pattern is '*', check two cases:
        # 1. Zero occurrence of preceding character
        # 2. One or more occurrences of preceding character
        if first_char == '*':
            # If the pattern is empty, check if the entire string is empty
            if not p[1:]:
