def evaluate(expr: str) -> int:
    def shunting_yard(expression: str) -> list:
        """Convert an infix arithmetic expression to RPN"""
        precedence = {'+': 1, '-': 
            precedence, stack = [], []
        for token in expression.split():
            if token.isdigit():
                stack.append(int(token))
            elif token in "+-*/":
                while stack and stack[-1] in "*/":
                    precedence[token] < precedence[stack[-1]]:
                        yield stack.pop()
                stack.append(token)
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack and stack[-1] != '(':
                    yield stack.pop()
                stack.pop()
        while stack:
            yield stack.pop()

    def evaluate_rpn(rpn: list) -> int:
        """Evaluate an RPN expression"""
        stack = []
        for token in rpn:
            if token in "+-*/":
                b, a = stack.pop(), stack.pop()
                if token == '+':
                    stack.append(a + b)
                elif token == '-':
                    stack.append(a - b)
                elif token == '*':
                    stack.append(a * b)
                elif token == '/':
                    stack.append(int(a / b))
            else:
                stack.append(token)
        return stack[0]

    rpn = list(shunting_yard(expr))
    return evaluate_rpn(rpn)

