def evaluate(expr: str) -> int:
    def apply_op(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left // right)

    def greater_precedence(op1, op2):
        precedences = {'+': 1, '-': 1, '*': 2, '/': 2}
        return precedences[op1] > precedences[op2]

    def evaluate_expression(expr: str):
        values = []
        operators = []
        number = ''
        for c in expr:
            if c.isdigit():
                number += c
            else:
                if number:
                    values.append(int(number))
                    number = ''
                if c in {'+', '-', '*', '/'}:
                    while (operators and operators[-1] in {'+', '-', '*', '/'} and
                           greater_precedence(operators[-1], c)):
                        apply_op(operators, values)
                    operators.append(c)
                elif c in {'(', ')'}:
                    if c == '(':
                        operators.append(c)
                    else:
                        while operators[-1] != '(':
                            apply_op(operators, values)
                        operators.pop()  # Remove '('
        if number:
            values.append(int(number))
        while operators:
            apply_op(operators, values)
        return values[-1]

    return evaluate_expression(expr)

