def evaluate(expr: str) -> int:
    def apply_op(op: str, second: int, first: int) -> int:
        if op == '+':
            return first + second
        if op == '-':
            return first - second
        if op == '*':
            return first * second
        if op == '/':
            return first // second

    def precedence(op: str) -> int:
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def greater_precedence(op1: str, op2: str) -> bool:
        return precedence(op1) >= precedence(
            op2)

    def evaluate_expression(tokens: list) -> int:
        values = []
        ops = []
        i = 0
        while i < len(tokens):
            if tokens[i] == '(':
                ops.append(tokens[i])
            elif tokens[i] == ')':
                while ops[-1] != '(':
                    values.append(
                        apply_op(ops.pop(), values.pop(), values.pop()))
                ops.pop()
            else:
                while (ops and
                       greater_precedence(ops[-1], tokens[i]) and
                       precedence(tokens[i]) <= precedence(ops[-1])):
                    values.append(
                        apply_op(ops.pop(), values.pop(), values.pop()))
                ops.append(tokens[i])
            i += 1
        while ops:
            values.append(
                apply_op(ops.pop(), values.pop(), values.pop()))
        return values[0]

    def tokenize(expr: str) -> list:
        token_expr = expr.split()
        return token_expr

    tokens = tokenize(expr)
    return evaluate_expression(tokens)

