```python
def edit_distance(a: str, b: str) -> int:
    # Create a matrix of size (len(a) + 1) x (len(b) + 1)
    distances = [[0 for j in range(len(b) + 1)] for i in range(len(a) + 1)]

    # Initialize the first row and first column of the matrix
    for i in range(len(a) + 1):
        distances[i][0] = i
    for j in range(len(b) + 1):
        distances[0][j] = j

    # Fill the matrix with the minimum number of operations
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i-1] == b[j-1]:
                distances[i][j] = distances[i-1][j-1]  # No operation needed
            else:
                distances[i][j] = 1 + min(distances[i-1][j],  # Deletion
                                          distances[i][j-1],  # Insertion
                                          distances[i-1][j-1])  # Substitution

    return distances[-1][-1]

